spring:
  datasource:
    driverClassName: com.mysql.jdbc.Driver
    url: jdbc:mysql://${mysql_host:172.23.0.24}:${mysql_port:3306}/${mysql_dbname:ice_vehicle}?charset=utf8
    username: ${mysql_username}
    password: ${mysql_password}
  redis:
    host: ${redis_host}
    port: ${redis_port:6379}
    password: ${redis_password}
    database: ${redis_db:2}
  kafka:
    bootstrap-servers: ${kafka_servers}
    consumer:
      group:
        id: ${groupId:triggered_event}
      heartbeat:
        interval:
          ms: 1500
      max:
        poll:
          records: ${kafka_records:512}
          interval:
            ms: 480000
      session:
        timout:
          ms: 30000
      bootstrap:
        servers: ${kafka_servers:172.21.0.93:9092}
      enable-auto-commit: true
    properties:
      triggeredEventTopic: ${triggeredEventTopic:predictive_event}

eureka:
  client:
    registerWithEureka: true
    fetchRegistry: true
    serviceUrl:
      defaultZone: http://${eureka_server}:${eureka_port}/eureka/
    enabled: true
  instance:
    preferIpAddress: ${preferIpAddress:true}
    leaseRenewalIntervalInSeconds: 10
    metadataMap:
      instanceId: ${vcap.application.instance_id:${spring.application.name}:${spring.application.instance_id:${server.port}}}
ribbon:
  ConnectionTimeout: 5000 #请求连接的超时时间
  ReadTimeout: 70000 #请求处理的超时时间
feign:
  httpclient:
    enabled: true
    max-connections: 3000 #最大连接数
    max-connections-per-route: 600 #每个路径最大连接数
  client:
    config:
      default:
        connectTimeout: 10000
        readTimeout: 70000
  url:
    dflzApi: ${dflzApiUrl:http://downlink-command-dispatcher.dflq-pv-uat-vap.svc.cluster.local:8080/dflz/api}

logging:
  level:
    root: ${loggingLevel:info}
  config: classpath:logback.xml

properties:
  xxxUrl: ${amspUrl:http://dflquat.sh.1255582006.clb.myqcloud.com:8005/amsp-service}

dlc:
  endpoint: dlc.tencentcloudapi.com
  secretId: AKIDOdhYBcooaBZkiaGiwwiFYdWBbnkSxHNH
  secretKey: kGZfXBlEYo3DLRPBrNisoY5QYTBh1B8r
  taskType: SparkSQLTask
  databaseName: ${databaseName:vehicle_fault_playback_uat}
  datasourceConnectionName: DataLakeCatalog
  region: ap-shanghai
  dataEngineName: dp-spark
  cosBucketName: ${cos_bucket:uat-dp-query-data-1255582006}
  cloudUid: ${qCloudUid:1255582006}
  exportVehiclePowerStatusTaskSparkAppName: ${exportVehiclePowerStatusTaskSparkAppName:spark_test}
  callbackUrl: ${callbackUrl:http://dflquat.sh.1255582006.clb.myqcloud.com:8005}
  reqDownloadOriginalToCosUrl: ${reqDownloadOriginalToCosUrl:http://dflqlive.sh.1255582006.clb.myqcloud.com:8005}
  socketTimeout: ${socketTimeout:60000}

# 腾讯云对象存储
cos:
  properties:
    app_id: ${cos_app_id:1255582006}
    secret_id: ${cos_secret_id:AKIDOdhYBcooaBZkiaGiwwiFYdWBbnkSxHNH}
    secret_key: ${cos_secret_key:kGZfXBlEYo3DLRPBrNisoY5QYTBh1B8r}
    cos_url: ${cos_bucket:/uat/original_triggered_data_file/}
    dpBucket: ${dp_bucket:vehicle-fault-playback-1255582006}
    region: ${cos_region:ap-shanghai}
    prefix: ${cos_prefix:uat/original_triggered_data_file/}
    suffix: ${cos_suffix:.zst}

